import Foundation

/// 一段真实的 Magic Mouse 滚动录制（2026-11-11，用户在记录窗口里滚的 36 次拨动：慢滚、快甩、换方向）。
///
/// 每项是「距上一个事件的毫秒数,phase,momentumPhase,scrollingDeltaY（pt）」，phase / momentumPhase 是 `NSEvent.Phase` 的原值
/// （began 1、changed 4、ended 8）。超过 400 ms 的停顿压成 400 ms。
///
/// 这段录制的特点（也是它要护住的东西）：连续拨动时，下一次手指碰上去会把上一次的惯性直接掐断——惯性结束那一刻
/// 每个事件还在走 100 多 pt；抬手到惯性开始只隔 0–32 ms，惯性被掐断到下一次拨动开始隔 50–70 ms。
nonisolated enum MagicMouseScrollRecording {
    struct Event {
        var delayMs: Int
        var phase: Int
        var momentum: Int
        var deltaY: Int
    }

    static let events: [Event] = raw.split(separator: ";").map { item in
        let f = item.split(separator: ",").map { Int($0)! }
        return Event(delayMs: f[0], phase: f[1], momentum: f[2], deltaY: f[3])
    }

